BEGIN;
CREATE TABLE IF NOT EXISTS public.sync_changes (sequence_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,collection text NOT NULL,action text NOT NULL CHECK(action IN('upsert','delete')),record_id text NOT NULL,record jsonb NOT NULL DEFAULT '{}'::jsonb,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_sync_changes_sequence ON public.sync_changes(sequence_id);
ALTER TABLE public.sync_changes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS sync_changes_none ON public.sync_changes;
CREATE POLICY sync_changes_none ON public.sync_changes FOR ALL TO authenticated USING(false) WITH CHECK(false);
REVOKE ALL ON public.sync_changes FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.record_sync_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r jsonb; i text; a text; c text:=TG_ARGV[0]; BEGIN IF TG_OP='DELETE' THEN r:=to_jsonb(OLD); a:='delete'; ELSE r:=to_jsonb(NEW); a:='upsert'; END IF; i:=coalesce(r->>'id',r->>'user_id',r->>'key'); IF nullif(i,'') IS NOT NULL THEN INSERT INTO public.sync_changes(collection,action,record_id,record) VALUES(c,a,i,r); END IF; RETURN coalesce(NEW,OLD); END; $$;
DROP TRIGGER IF EXISTS trg_sync_users ON public.users; CREATE TRIGGER trg_sync_users AFTER INSERT OR UPDATE OR DELETE ON public.users FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('profiles');
DROP TRIGGER IF EXISTS trg_sync_properties ON public.properties; CREATE TRIGGER trg_sync_properties AFTER INSERT OR UPDATE OR DELETE ON public.properties FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('properties');
DROP TRIGGER IF EXISTS trg_sync_contractors ON public.contractors; CREATE TRIGGER trg_sync_contractors AFTER INSERT OR UPDATE OR DELETE ON public.contractors FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('contractors');
DROP TRIGGER IF EXISTS trg_sync_registrations ON public.registrations; CREATE TRIGGER trg_sync_registrations AFTER INSERT OR UPDATE OR DELETE ON public.registrations FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('registrations');
DROP TRIGGER IF EXISTS trg_sync_property_likes ON public.property_likes; CREATE TRIGGER trg_sync_property_likes AFTER INSERT OR UPDATE OR DELETE ON public.property_likes FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('propertyLikes');
DROP TRIGGER IF EXISTS trg_sync_property_saves ON public.property_saves; CREATE TRIGGER trg_sync_property_saves AFTER INSERT OR UPDATE OR DELETE ON public.property_saves FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('propertySaves');
DROP TRIGGER IF EXISTS trg_sync_contractor_likes ON public.contractor_likes; CREATE TRIGGER trg_sync_contractor_likes AFTER INSERT OR UPDATE OR DELETE ON public.contractor_likes FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('contractorLikes');
DROP TRIGGER IF EXISTS trg_sync_viewing_requests ON public.viewing_requests; CREATE TRIGGER trg_sync_viewing_requests AFTER INSERT OR UPDATE OR DELETE ON public.viewing_requests FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('viewingRequests');
DROP TRIGGER IF EXISTS trg_sync_quote_requests ON public.quote_requests; CREATE TRIGGER trg_sync_quote_requests AFTER INSERT OR UPDATE OR DELETE ON public.quote_requests FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('quoteRequests');
DROP TRIGGER IF EXISTS trg_sync_share_requests ON public.student_share_requests; CREATE TRIGGER trg_sync_share_requests AFTER INSERT OR UPDATE OR DELETE ON public.student_share_requests FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('shareRequests');
DROP TRIGGER IF EXISTS trg_sync_student_interests ON public.student_interests; CREATE TRIGGER trg_sync_student_interests AFTER INSERT OR UPDATE OR DELETE ON public.student_interests FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('studentInterests');
DROP TRIGGER IF EXISTS trg_sync_messages ON public.messages; CREATE TRIGGER trg_sync_messages AFTER INSERT OR UPDATE OR DELETE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.record_sync_change('messages');
CREATE TABLE IF NOT EXISTS public.sync_idempotency(actor_user_id text NOT NULL,mutation_id text NOT NULL,operation text NOT NULL,response jsonb NOT NULL,status_code integer NOT NULL DEFAULT 200,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT(now()+interval '30 days'),PRIMARY KEY(actor_user_id,mutation_id));
CREATE INDEX IF NOT EXISTS idx_sync_idempotency_expiry ON public.sync_idempotency(expires_at);
ALTER TABLE public.sync_idempotency ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS sync_idempotency_none ON public.sync_idempotency;
CREATE POLICY sync_idempotency_none ON public.sync_idempotency FOR ALL TO authenticated USING(false) WITH CHECK(false);
REVOKE ALL ON public.sync_idempotency FROM anon,authenticated;
CREATE OR REPLACE FUNCTION public.sync_get_idempotent_response(p_mutation_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN SELECT jsonb_build_object('status_code',status_code,'response',response) INTO v FROM public.sync_idempotency WHERE actor_user_id=auth.uid()::text AND mutation_id=left(p_mutation_id,255) AND expires_at>now(); RETURN v; END; $$;
GRANT EXECUTE ON FUNCTION public.sync_get_idempotent_response(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.sync_store_idempotent_response(p_mutation_id text,p_operation text,p_response jsonb,p_status_code integer DEFAULT 200) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN IF nullif(trim(p_mutation_id),'') IS NULL THEN RAISE EXCEPTION 'SYNC_MUTATION_ID_REQUIRED'; END IF; INSERT INTO public.sync_idempotency(actor_user_id,mutation_id,operation,response,status_code) VALUES(auth.uid()::text,left(p_mutation_id,255),left(coalesce(p_operation,''),100),coalesce(p_response,'{}'::jsonb),p_status_code) ON CONFLICT DO NOTHING; SELECT jsonb_build_object('status_code',status_code,'response',response) INTO v FROM public.sync_idempotency WHERE actor_user_id=auth.uid()::text AND mutation_id=left(p_mutation_id,255); RETURN v; END; $$;
GRANT EXECUTE ON FUNCTION public.sync_store_idempotent_response(text,text,jsonb,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.sync_changes_after(p_cursor bigint DEFAULT 0,p_limit integer DEFAULT 200) RETURNS TABLE(sequence_id bigint,collection text,action text,record_id text,record jsonb,occurred_at timestamptz) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT sequence_id,collection,action,record_id,record,occurred_at FROM public.sync_changes WHERE auth.uid() IS NOT NULL AND sequence_id>greatest(coalesce(p_cursor,0),0) ORDER BY sequence_id LIMIT least(greatest(coalesce(p_limit,200),1),500); $$;
GRANT EXECUTE ON FUNCTION public.sync_changes_after(bigint,integer) TO authenticated;
NOTIFY pgrst,'reload schema'; COMMIT;
